extractedSpecialRules:
@keyframes toast-in { 
  0% { opacity: 0; transform: translateY(-12px); }
  100% { opacity: 1; transform: none; }
}

@keyframes anat-callout-in { 
  0% { opacity: 0; transform: translateY(3px) scale(0.9); }
  100% { opacity: 1; transform: translateY(0px) scale(1); }
}

@keyframes backlog-move { 
  0% { transform: translateY(20px); opacity: 0.5; }
  100% { transform: translateY(0px); opacity: 1; }
}

@keyframes gantt-shift { 
  0% { transform: translateX(-48px); opacity: 0.6; }
  100% { transform: translateX(0px); opacity: 1; }
}

@keyframes fj-pulse { 
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.15); opacity: 0.75; }
}

@keyframes selector-mini-cursor-cycle { 
  0%, 6% { left: 82%; top: 70%; opacity: 0; transform: scale(1); }
  13% { opacity: 1; }
  31% { left: 24%; top: 76%; opacity: 1; transform: scale(1); }
  35% { left: 24%; top: 76%; transform: scale(0.76); }
  39%, 82% { left: 24%; top: 76%; opacity: 1; transform: scale(1); }
  91%, 100% { left: 24%; top: 76%; opacity: 0; }
}

@keyframes selector-mini-target-cycle { 
  0%, 25% { border-style: dashed; opacity: 0; transform: scale(0.98); }
  29%, 34% { border-style: dashed; opacity: 0.62; transform: scale(1); }
  39% { border-style: solid; opacity: 1; transform: scale(1.06); }
  44%, 84% { border-style: solid; opacity: 1; transform: scale(1); }
  93%, 100% { opacity: 0; }
}

@keyframes selector-mini-note-cycle { 
  0%, 43% { opacity: 0; transform: translateY(5px); }
  49%, 82% { opacity: 1; transform: translateY(0px); }
  92%, 100% { opacity: 0; }
}

@keyframes selector-mini-copied-cycle { 
  0%, 58% { opacity: 0; transform: translateY(3px); }
  64%, 84% { opacity: 1; transform: translateY(0px); }
  93%, 100% { opacity: 0; }
}

@keyframes anim-demo-move { 
  0% { left: 8px; transform: scale(1); }
  50% { transform: scale(1.25); }
  100% { left: calc(100% - 26px); transform: scale(1); }
}

@keyframes spring-demo-pop { 
  0% { left: 8px; }
  42% { left: calc(70% + 26px); }
  58% { left: calc(70% - 14px); }
  72% { left: calc(70% + 5px); }
  82%, 100% { left: calc(70% - 9px); }
}

